import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { CategoriaService, Categoria } from '../../services/categoria.service';
import { ExportService } from '../../services/export.service';

// ========================================================================
// COMPONENTE
// ========================================================================

@Component({
  selector: 'app-categorias',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './categorias.component.html',
  styleUrls: ['./categorias.component.scss']
})
export class CategoriasComponent implements OnInit {
  // ====================================================================
  // ESTADO
  // ====================================================================

  categorias: Categoria[] = [];
  categoriasReceita: Categoria[] = [];
  categoriasDespesa: Categoria[] = [];
  
  mostrarForm = false;
  isLoading = false;
  isSaving = false;
  isExporting = false;
  hasError = false;
  errorMessage = '';
  editandoId: number | null = null;

  categoriaForm: FormGroup;

  // ====================================================================
  // CONSTRUTOR
  // ====================================================================

  constructor(
    private categoriaService: CategoriaService,
    private exportService: ExportService,
    private fb: FormBuilder
  ) {
    this.categoriaForm = this.criarFormulario();
  }

  // ====================================================================
  // LIFECYCLE
  // ====================================================================

  ngOnInit(): void {
    this.carregarCategorias();
  }

  // ====================================================================
  // MÉTODOS PRIVADOS
  // ====================================================================

  /**
   * Cria um novo FormGroup para o formulário de categorias
   */
  private criarFormulario(): FormGroup {
    return this.fb.group({
      nome: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(50)]],
      tipo: ['receita', [Validators.required]]
    });
  }

  /**
   * Reseta o formulário aos valores padrão
   */
  private resetarFormulario(): void {
    this.categoriaForm.reset({
      nome: '',
      tipo: 'receita'
    });
    this.editandoId = null;
  }

  /**
   * Segrega as categorias por tipo
   */
  private segregarCategorias(): void {
    this.categoriasReceita = this.categorias.filter(c => c.tipo === 'receita');
    this.categoriasDespesa = this.categorias.filter(c => c.tipo === 'despesa');
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - CARREGAMENTO
  // ====================================================================

  /**
   * Carrega a lista de categorias da API
   */
  carregarCategorias(): void {
    this.isLoading = true;
    this.hasError = false;

    this.categoriaService.listar().subscribe({
      next: (response) => {
        if (response.success && response.data) {
          const data = response.data as Categoria[];
          this.categorias = Array.isArray(data) ? data : [data];
          this.segregarCategorias();
        } else {
          this.categorias = [];
          this.categoriasReceita = [];
          this.categoriasDespesa = [];
        }
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Erro ao carregar categorias:', error);
        this.hasError = true;
        this.errorMessage = 'Erro ao carregar as categorias. Tente novamente.';
        this.isLoading = false;
      }
    });
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - FORMULÁRIO
  // ====================================================================

  /**
   * Alterna a visibilidade do formulário
   */
  toggleFormulario(): void {
    this.mostrarForm = !this.mostrarForm;
    if (!this.mostrarForm) {
      this.resetarFormulario();
    }
  }

  /**
   * Abre o formulário para editar uma categoria
   */
  editar(categoria: Categoria): void {
    this.editandoId = categoria.id || null;
    this.categoriaForm.patchValue({
      nome: categoria.nome,
      tipo: categoria.tipo
    });
    this.mostrarForm = true;
  }

  /**
   * Cancela a edição/criação e fecha o formulário
   */
  cancelar(): void {
    this.mostrarForm = false;
    this.resetarFormulario();
  }

  /**
   * Salva a categoria (cria ou atualiza)
   */
  salvar(): void {
    if (!this.categoriaForm.valid) {
      this.errorMessage = 'Por favor, preencha todos os campos corretamente.';
      return;
    }

    this.isSaving = true;
    const formValue = this.categoriaForm.value;

    if (this.editandoId) {
      // Atualizar categoria existente
      this.categoriaService.atualizar(this.editandoId, formValue).subscribe({
        next: () => {
          this.carregarCategorias();
          this.cancelar();
          this.isSaving = false;
        },
        error: (error) => {
          console.error('Erro ao atualizar categoria:', error);
          this.errorMessage = 'Erro ao atualizar a categoria. Tente novamente.';
          this.isSaving = false;
        }
      });
    } else {
      // Criar nova categoria
      this.categoriaService.criar(formValue).subscribe({
        next: () => {
          this.carregarCategorias();
          this.cancelar();
          this.isSaving = false;
        },
        error: (error) => {
          console.error('Erro ao criar categoria:', error);
          this.errorMessage = 'Erro ao criar a categoria. Tente novamente.';
          this.isSaving = false;
        }
      });
    }
  }

  /**
   * Remove uma categoria
   */
  deletar(categoria: Categoria): void {
    if (!categoria.id) return;

    if (confirm(`Tem a certeza que deseja eliminar a categoria "${categoria.nome}"?`)) {
      this.categoriaService.remover(categoria.id).subscribe({
        next: () => {
          this.carregarCategorias();
        },
        error: (error) => {
          console.error('Erro ao deletar categoria:', error);
          this.errorMessage = 'Erro ao eliminar a categoria. Tente novamente.';
        }
      });
    }
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - EXPORTAÇÃO
  // ====================================================================

  /**
   * Inicia o download do relatório CSV
   */
  exportarCsv(): void {
    this.isExporting = true;
    this.hasError = false;

    this.exportService.exportarCsv('relatorio_financeiro.csv')
      .then(() => {
        this.isExporting = false;
      })
      .catch((error) => {
        console.error('Erro ao exportar:', error);
        this.hasError = true;
        this.errorMessage = error.message || 'Erro ao exportar o relatório. Tente novamente.';
        this.isExporting = false;
      });
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - HELPERS
  // ====================================================================

  /**
   * Retorna o titulo do formulário
   */
  getTituloFormulario(): string {
    return this.editandoId ? 'Editar Categoria' : 'Nova Categoria';
  }

  /**
   * Retorna o texto do botão de salvar
   */
  getTextoBotaoSalvar(): string {
    return this.editandoId ? 'Atualizar' : 'Criar';
  }

  /**
   * Verifica se está em modo edição
   */
  isEditando(): boolean {
    return this.editandoId !== null;
  }

  /**
   * Retorna o rótulo do tipo de categoria
   */
  getLabelTipo(tipo: string): string {
    return tipo === 'receita' ? '↓ Receita' : '↑ Despesa';
  }
}
<!-- ======================================================================== -->
<!-- CONTAINER PRINCIPAL -->
<!-- ======================================================================== -->

<div class="categorias-container">
  
  <!-- ====================================================================== -->
  <!-- CABEÇALHO COM TÍTULO E BOTÕES -->
  <!-- ====================================================================== -->

  <div class="categorias-header">
    <h1>Categorias Financeiras</h1>
    <div class="header-actions">
      <button 
        class="btn btn-success" 
        (click)="exportarCsv()"
        [disabled]="isLoading || isExporting"
        title="Baixar relatório em formato CSV">
        <span *ngIf="!isExporting">📊 Exportar Relatório CSV</span>
        <span *ngIf="isExporting">⏳ Exportando...</span>
      </button>
      <button 
        class="btn btn-primary" 
        (click)="toggleFormulario()"
        [disabled]="isLoading">
        <span *ngIf="!mostrarForm">+ Nova Categoria</span>
        <span *ngIf="mostrarForm">✕ Cancelar</span>
      </button>
    </div>
  </div>

  <!-- ======================================================================== -->
  <!-- MENSAGEM DE ERRO -->
  <!-- ======================================================================== -->

  <div *ngIf="hasError" class="alert alert-error">
    <strong>Erro:</strong> {{ errorMessage }}
    <button class="alert-close" (click)="hasError = false">✕</button>
  </div>

  <!-- ======================================================================== -->
  <!-- ESTADO DE CARREGAMENTO -->
  <!-- ======================================================================== -->

  <div *ngIf="isLoading" class="loading-container">
    <div class="spinner"></div>
    <p>Carregando categorias...</p>
  </div>

  <!-- ======================================================================== -->
  <!-- FORMULÁRIO -->
  <!-- ======================================================================== -->

  <div *ngIf="mostrarForm && !isLoading" class="formulario-container">
    <h2>{{ getTituloFormulario() }}</h2>
    
    <form [formGroup]="categoriaForm" (ngSubmit)="salvar()" class="categoria-form">
      <!-- Campo: Nome -->
      <div class="form-group">
        <label for="nome">Nome da Categoria</label>
        <input 
          type="text" 
          id="nome"
          formControlName="nome"
          placeholder="Ex: Alimentação, Transporte, etc."
          class="form-control">
        <span *ngIf="categoriaForm.get('nome')?.invalid && categoriaForm.get('nome')?.touched" 
              class="error-message">
          <span *ngIf="categoriaForm.get('nome')?.errors?.['required']">Nome é obrigatório</span>
          <span *ngIf="categoriaForm.get('nome')?.errors?.['minlength']">Nome deve ter pelo menos 3 caracteres</span>
          <span *ngIf="categoriaForm.get('nome')?.errors?.['maxlength']">Nome não pode exceder 50 caracteres</span>
        </span>
      </div>

      <!-- Campo: Tipo -->
      <div class="form-group">
        <label for="tipo">Tipo</label>
        <div class="tipo-options">
          <label class="radio-label">
            <input 
              type="radio" 
              id="tipo-receita"
              value="receita" 
              formControlName="tipo"
              class="radio-input">
            <span class="radio-text receita">Receita</span>
          </label>
          <label class="radio-label">
            <input 
              type="radio" 
              id="tipo-despesa"
              value="despesa" 
              formControlName="tipo"
              class="radio-input">
            <span class="radio-text despesa">Despesa</span>
          </label>
        </div>
      </div>

      <!-- Botões -->
      <div class="form-actions">
        <button 
          type="submit" 
          class="btn btn-success"
          [disabled]="!categoriaForm.valid || isSaving">
          <span *ngIf="!isSaving">{{ getTextoBotaoSalvar() }}</span>
          <span *ngIf="isSaving">Guardando...</span>
        </button>
        <button 
          type="button" 
          class="btn btn-secondary"
          (click)="cancelar()"
          [disabled]="isSaving">
          Cancelar
        </button>
      </div>
    </form>
  </div>

  <!-- ======================================================================== -->
  <!-- ESTADO VAZIO -->
  <!-- ======================================================================== -->

  <div *ngIf="!isLoading && categorias.length === 0 && !mostrarForm" class="empty-state">
    <div class="empty-icon">📁</div>
    <h3>Nenhuma categoria registada</h3>
    <p>Clique em "+ Nova Categoria" para criar suas primeiras categorias financeiras.</p>
  </div>

  <!-- ======================================================================== -->
  <!-- CONTEÚDO - GRELHA DE CATEGORIAS -->
  <!-- ======================================================================== -->

  <div *ngIf="!isLoading && categorias.length > 0 && !mostrarForm" class="categorias-content">
    
    <!-- SECÇÃO: RECEITAS -->
    <div *ngIf="categoriasReceita.length > 0" class="categoria-section">
      <h2 class="section-title">
        <span class="section-icon receita">↓</span>
        Categorias de Receita
        <span class="section-count">({{ categoriasReceita.length }})</span>
      </h2>
      
      <div class="categorias-grid">
        <div *ngFor="let cat of categoriasReceita" class="categoria-card receita-card">
          <div class="card-content">
            <h3 class="card-title">{{ cat.nome }}</h3>
            <span class="card-badge receita">Receita</span>
          </div>
          
          <div class="card-actions">
            <button 
              class="btn btn-sm btn-primary" 
              (click)="editar(cat)"
              title="Editar">
              ✏️
            </button>
            <button 
              class="btn btn-sm btn-error" 
              (click)="deletar(cat)"
              title="Eliminar">
              🗑️
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- SEPARADOR -->
    <div *ngIf="categoriasReceita.length > 0 && categoriasDespesa.length > 0" class="section-divider"></div>

    <!-- SECÇÃO: DESPESAS -->
    <div *ngIf="categoriasDespesa.length > 0" class="categoria-section">
      <h2 class="section-title">
        <span class="section-icon despesa">↑</span>
        Categorias de Despesa
        <span class="section-count">({{ categoriasDespesa.length }})</span>
      </h2>
      
      <div class="categorias-grid">
        <div *ngFor="let cat of categoriasDespesa" class="categoria-card despesa-card">
          <div class="card-content">
            <h3 class="card-title">{{ cat.nome }}</h3>
            <span class="card-badge despesa">Despesa</span>
          </div>
          
          <div class="card-actions">
            <button 
              class="btn btn-sm btn-primary" 
              (click)="editar(cat)"
              title="Editar">
              ✏️
            </button>
            <button 
              class="btn btn-sm btn-error" 
              (click)="deletar(cat)"
              title="Eliminar">
              🗑️
            </button>
          </div>
        </div>
      </div>
    </div>

  </div>

</div>
